/**
 * A string drawn as a scannable QR Code symbol (`design/components/qr-code.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/qr-code.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, type JSX } from 'solid-js'

import {
  QR_QUIET_ZONE,
  claimSlot,
  createDerived,
  devWarning,
  qrPath,
  qrSymbol,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/qr-code.module.css'

export type QRCodeSize = NonNullable<QRCodeProps['size']>

export type QRCodeErrorCorrection = NonNullable<QRCodeProps['errorCorrection']>

export interface QRCodeProps {
  /**
   * Damage tolerance: `L` 7%, `M` 15%, `Q` 25%, `H` 30%. More correction means a denser symbol,
   * the worse trade on a screen: displays do not get scuffed, and dense symbols scan worse at
   * arm's length. `M` is the screen default.
   */
  errorCorrection?: 'L' | 'M' | 'Q' | 'H'
  /**
   * The accessible name: what the symbol is *for* ("Authenticator setup code"), never its
   * contents. Required, because the symbol is noise to a reader who cannot scan it.
   */
  label: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * The content, encoded as UTF-8; always controlled, as the symbol is a pure function of it.
   */
  value: string
}

/** A string drawn as a scannable QR Code symbol. */
export default function QRCode(given: QRCodeProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', errorCorrection: 'M' } as Defaults<QRCodeProps, 'size' | 'errorCorrection'>,
    claimSlot(given),
  )
  const symbol = createDerived(() => qrSymbol(props.value, props.errorCorrection))
  const extent = createDerived(() =>
    symbol.value === null ? 0 : symbol.value.size + QR_QUIET_ZONE * 2,
  )
  const ink = createDerived(() =>
    symbol.value === null ? '' : qrPath(symbol.value, QR_QUIET_ZONE),
  )
  const effect1 = () => {
    devWarning(
      symbol.value === null,
      `QRCode: \`value\` (${props.value.length} characters) does not fit a QR symbol at correction level ${props.errorCorrection}. Nothing was rendered.`,
    )
  }
  watchEffect(
    createMemo(() => [symbol.value, props.errorCorrection]),
    effect1,
    true,
  )
  const effect2 = () => {
    devWarning(props.value === '', 'QRCode: `value` is empty. Nothing was rendered.')
  }
  watchEffect(
    createMemo(() => props.value),
    effect2,
    true,
  )
  return (
    <>
      {symbol.value !== null && props.value !== '' ? (
        <svg
          class={styles.symbol}
          viewBox={`0 0 ${extent.value} ${extent.value}`}
          role="img"
          aria-label={props.label}
          shape-rendering="crispEdges"
          data-size={props.size}
          data-mode="light"
          data-member="qr-code"
        >
          {/* paper */}
          <rect class={styles.paper} width={extent.value} height={extent.value} />
          {/* ink */}
          <path class={styles.ink} d={ink.value} />
        </svg>
      ) : null}
    </>
  )
}
